            healthDisplay.remove();
        }

        console.log('🎉 VICTORY! Dungeon cleared!');

        if (typeof notify === 'function') {
            notify(`🎉 VICTORY! Level ${currentDungeon.level} cleared!`, 'success');
        }

        // Show victory UI (TODO)
        showVictoryScreen();
    }

