    # ===== CHROMADB MEMORY CONTEXT =====
    memory_context = ""
    if NAJIKA_MEMORY:
        try:
            memory_context = NAJIKA_MEMORY.build_context_prompt(user_text, n_memories=3)
            if memory_context:
                memory_context = f"\n\n{memory_context}\n"
        except Exception as e:
            log("WARNING", f"Memory Retrieval Fehler: {e}", "MEMORY")

